# -*- coding: utf-8 -*-
"""IMP2 Arrow Helper v5 (해상도 대응판)

해상도/배율이 달라도 동작하도록 캡처 부분만 수정함. 인식/입력 로직은 v5 그대로.
- 게임 창(클라이언트 영역) 크기를 기준으로 1080p 크기로 맞춰서 매칭
- 화면 전체가 아니라 필요한 영역만 캡처 (고해상도에서도 빠름)
- 윈도우 배율(125%, 150%)에 영향받지 않도록 DPI 인식 설정

규칙:
- 회피 1회는 같은 방향 3줄로 표시됨.
- 화면 아래쪽의 최신 3줄만 확인.
- 최신 3줄이 같은 방향이면 그 방향키를 딱 1회 입력.
- 기존 3줄이 위로 밀려 남아 있어도 다시 누르지 않음.
- 새 3줄이 아래에 추가되었을 때만 다시 1회 입력.
F8 = ON/OFF, F9 = 종료
"""
import base64, ctypes, time, threading, traceback, os, sys
from ctypes import wintypes

# 윈도우 디스플레이 배율(125%, 150% 등) 때문에 화면 크기/좌표가 틀어지는 것을 방지
try:
    ctypes.windll.shcore.SetProcessDpiAwareness(2)
except Exception:
    try:
        ctypes.windll.user32.SetProcessDPIAware()
    except Exception:
        pass
try:
    import cv2, numpy as np
except Exception as e:
    msg='OpenCV/NumPy 로드 실패\n\n'+repr(e)+'\n\nPython/패키지 설치 상태를 확인하세요.'
    try:
        ctypes.windll.user32.MessageBoxW(0,msg,'IMP2 Arrow Helper 시작 오류',0x10)
    except Exception:
        pass
    raise

TEMPLATES_B64 = {'up': '', 'down': '', 'left': '', 'right': ''}
VK={'up':0x26,'down':0x28,'left':0x25,'right':0x27}
ORDER=['up','down','left','right']
ROI_1920=(240,430,850,720)
BASE_ROI_W=ROI_1920[2]-ROI_1920[0]; BASE_ROI_H=ROI_1920[3]-ROI_1920[1]   # 1080p 기준 검사 영역 크기(템플릿과 같은 스케일)
MATCH_THRESHOLD=0.58
SCAN_INTERVAL=0.01
ROW_Y_TOL=8

user32=ctypes.windll.user32; gdi32=ctypes.windll.gdi32
class BITMAPINFOHEADER(ctypes.Structure):
    _fields_=[('biSize',wintypes.DWORD),('biWidth',wintypes.LONG),('biHeight',wintypes.LONG),('biPlanes',wintypes.WORD),('biBitCount',wintypes.WORD),('biCompression',wintypes.DWORD),('biSizeImage',wintypes.DWORD),('biXPelsPerMeter',wintypes.LONG),('biYPelsPerMeter',wintypes.LONG),('biClrUsed',wintypes.DWORD),('biClrImportant',wintypes.DWORD)]
class BITMAPINFO(ctypes.Structure):
    _fields_=[('bmiHeader',BITMAPINFOHEADER),('bmiColors',wintypes.DWORD*3)]
SRCCOPY=0x00CC0020; DIB_RGB_COLORS=0

def grab_region(x,y,w,h):
    """화면의 (x,y,w,h) 영역만 캡처한다. (전체 화면 캡처보다 훨씬 빠름)"""
    w=max(1,int(w)); h=max(1,int(h))
    hdc=user32.GetDC(0)
    if not hdc: raise RuntimeError('GetDC 실패')
    memdc=gdi32.CreateCompatibleDC(hdc)
    hbmp=gdi32.CreateCompatibleBitmap(hdc,w,h)
    if not memdc or not hbmp: raise RuntimeError('화면 캡처 객체 생성 실패')
    try:
        gdi32.SelectObject(memdc,hbmp)
        if not gdi32.BitBlt(memdc,0,0,w,h,hdc,int(x),int(y),SRCCOPY): raise RuntimeError('BitBlt 실패')
        bmi=BITMAPINFO(); bmi.bmiHeader.biSize=ctypes.sizeof(BITMAPINFOHEADER); bmi.bmiHeader.biWidth=w; bmi.bmiHeader.biHeight=-h; bmi.bmiHeader.biPlanes=1; bmi.bmiHeader.biBitCount=32; bmi.bmiHeader.biCompression=0
        buf=(ctypes.c_ubyte*(w*h*4))()
        if not gdi32.GetDIBits(memdc,hbmp,0,h,ctypes.byref(buf),ctypes.byref(bmi),DIB_RGB_COLORS): raise RuntimeError('GetDIBits 실패')
        return np.frombuffer(buf,np.uint8).reshape((h,w,4))[:,:,:3].copy()
    finally:
        gdi32.DeleteObject(hbmp); gdi32.DeleteDC(memdc); user32.ReleaseDC(0,hdc)

def game_rect():
    """게임 창 클라이언트 영역 (x,y,w,h). 얻지 못하면 전체 화면."""
    try:
        hwnd=user32.GetForegroundWindow()
        rc=wintypes.RECT(); pt=wintypes.POINT(0,0)
        if hwnd and user32.GetClientRect(hwnd,ctypes.byref(rc)) and user32.ClientToScreen(hwnd,ctypes.byref(pt)):
            w=rc.right-rc.left; h=rc.bottom-rc.top
            if w>=320 and h>=240: return pt.x,pt.y,w,h
    except Exception:
        pass
    return 0,0,user32.GetSystemMetrics(0),user32.GetSystemMetrics(1)

def decode_templates():
    out={}
    for d,b64 in TEMPLATES_B64.items():
        im=cv2.imdecode(np.frombuffer(base64.b64decode(b64),np.uint8),cv2.IMREAD_GRAYSCALE)
        if im is None: raise RuntimeError(d+' 이미지 디코딩 실패')
        out[d]=im
    return out
T=decode_templates()

def get_roi():
    """검사 영역을 캡처해서 항상 1080p 기준 크기(BASE_ROI_W x BASE_ROI_H)로 맞춰 돌려준다.
    1080p에서는 v5와 완전히 같은 이미지가 되고, 해상도가 높으면 줄여서 템플릿과 같은 크기로 만든다."""
    gx,gy,gw,gh=game_rect()
    sc=gh/1080.                      # 게임 UI는 화면 높이에 비례해서 커진다
    x1,y1,x2,y2=ROI_1920
    rx=gx+int(round(x1*sc)); ry=gy+int(round(y1*sc))
    rw=max(8,int(round(BASE_ROI_W*sc))); rh=max(8,int(round(BASE_ROI_H*sc)))
    rw=min(rw,gx+gw-rx); rh=min(rh,gy+gh-ry)
    roi=grab_region(rx,ry,rw,rh)
    if roi.shape[1]!=BASE_ROI_W or roi.shape[0]!=BASE_ROI_H:
        interp=cv2.INTER_AREA if sc>1 else cv2.INTER_CUBIC
        roi=cv2.resize(roi,(BASE_ROI_W,BASE_ROI_H),interpolation=interp)
    return roi

def _peaks(sm, threshold, min_gap=10, limit=20):
    s=sm.copy(); out=[]
    while len(out)<limit:
        _,v,_,loc=cv2.minMaxLoc(s)
        if v<threshold: break
        x,y=loc; out.append((int(y),float(v),int(x)))
        h=12; w=120
        y1=max(0,y-h); y2=min(s.shape[0],y+h+1); x1=max(0,x-w); x2=min(s.shape[1],x+w+1)
        s[y1:y2,x1:x2]=-1
    return out

def _direction_score(gray, x, y, d):
    # 방향명(위쪽/아래쪽/왼쪽/오른쪽)이 들어 있는 부분만 따로 비교한다.
    # 공통 문구인 "회피 : ["와 "화살표 키]" 때문에 up이 left로 오인되는
    # 문제를 막기 위한 보조 판별이다.
    t=T[d]
    x1=x+55
    y1=y
    h,w=t.shape[:2]
    x2=x1+min(90,w-55)
    if x1<0 or y1<0 or y1+h>gray.shape[0] or x2>gray.shape[1]:
        return -1.0
    patch=gray[y1:y1+h,x1:x2]
    templ=t[:,55:55+patch.shape[1]]
    if patch.shape != templ.shape or patch.size==0:
        return -1.0
    return float(cv2.matchTemplate(patch,templ,cv2.TM_CCOEFF_NORMED)[0,0])

def detect_rows(roi):
    gray=cv2.cvtColor(roi,cv2.COLOR_BGR2GRAY)
    raw=[]
    for d in ORDER:
        t=T[d]
        if gray.shape[0]<t.shape[0] or gray.shape[1]<t.shape[1]: continue
        sm=cv2.matchTemplate(gray,t,cv2.TM_CCOEFF_NORMED)
        for y,score,x in _peaks(sm,MATCH_THRESHOLD,min_gap=10,limit=20):
            raw.append({'y':y,'score':score,'d':d,'x':x,'dirscore':_direction_score(gray,x,y,d)})
    raw.sort(key=lambda r:r['y'])
    rows=[]
    for r in raw:
        if not rows or abs(r['y']-rows[-1]['y'])>ROW_Y_TOL:
            rows.append(r)
        else:
            cur=rows[-1]
            # 같은 줄에서는 기존 전체 템플릿 점수와 방향명 부분 점수를 함께 사용한다.
            # 특히 up/left처럼 공통 문구가 비슷한 경우 방향명 부분을 우선한다.
            r_key=0.35*r['score']+0.65*r['dirscore']
            c_key=0.35*cur['score']+0.65*cur['dirscore']
            if r_key>c_key:
                rows[-1]=r
    return [r for r in rows if r['score']>=MATCH_THRESHOLD]

def latest_three(rows):
    if len(rows)<3: return None
    last=rows[-3:]
    ds=[r['d'] for r in last]
    if not (ds[0]==ds[1]==ds[2]): return None
    # 세 줄 간격이 비정상적으로 벌어진 잡음은 제외
    gaps=[last[i+1]['y']-last[i]['y'] for i in range(2)]
    if not all(12<=g<=45 for g in gaps): return None
    return last[0]['d'], tuple(r['y'] for r in last)

def send_key(d):
    vk=VK[d]; user32.keybd_event(vk,0,0,0); time.sleep(.015); user32.keybd_event(vk,0,2,0)

def foreground_is_warcraft():
    hwnd=user32.GetForegroundWindow()
    if not hwnd: return False
    b=ctypes.create_unicode_buffer(512); user32.GetWindowTextW(hwnd,b,512); s=b.value.lower()
    return 'warcraft' in s or '워크래프트' in s

running=True; active=True
def keys():
    global running,active
    o8=o9=False
    while running:
        f8=bool(user32.GetAsyncKeyState(0x77)&0x8000); f9=bool(user32.GetAsyncKeyState(0x78)&0x8000)
        if f8 and not o8: active=not active; print('[IMP2] 자동입력 '+('ON' if active else 'OFF'),flush=True)
        if f9 and not o9: running=False
        o8,o9=f8,f9; time.sleep(.03)
threading.Thread(target=keys,daemon=True).start()
print('IMP2 Arrow Helper v5 (해상도 대응) | F8=ON/OFF | F9=종료',flush=True)
print('최신 아래쪽 3줄만 입력합니다.',flush=True)
last_signature=None
was_warcraft=False
while running:
    try:
        is_warcraft=foreground_is_warcraft()
        if not active or not is_warcraft:
            was_warcraft=False
            time.sleep(.10)
            continue
        # Alt+Tab 등으로 다른 창에 갔다가 워크래프트로 돌아오면
        # 이전 창에서 기억한 감지 상태를 버리고 현재 화면을 새로 감지한다.
        if not was_warcraft:
            last_signature=None
        was_warcraft=True
        rows=detect_rows(get_roi())
        sig=latest_three(rows)
        if sig is not None:
            d,ys=sig
            signature=(d,ys)
            if signature!=last_signature:
                print(f'[IMP2] 새 회피: {d} / y={ys} -> 키 1회',flush=True)
                send_key(d); last_signature=signature
        time.sleep(SCAN_INTERVAL)
    except Exception as e:
        print('[IMP2] ERROR:',repr(e),flush=True); time.sleep(.5)
print('IMP2 Arrow Helper 종료.',flush=True)
